import{_ as i,W as l,s as o,u as d,I as t,ah as r,w as n,Z as e,A as p}from"./chunks/framework.DPWZnL3N.js";import"./chunks/theme.DZmP8ALZ.js";const T=JSON.parse('{"title":"如何记录你在终端中执行的所有操作 | LCTT x X-CMD","titleTemplate":false,"description":"如何记录你在终端中执行的所有操作 | LCTT (201807) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"如何记录你在终端中执行的所有操作 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何记录你在终端中执行的所有操作 | LCTT (201807) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201807/20170309 How To Record Everything You Do In Terminal","title":"如何记录你在终端中执行的所有操作","tag":"201807"},"relativePath":"201807/20170309 How To Record Everything You Do In Terminal.md","filePath":"[post].md"}'),u={name:"201807/20170309 How To Record Everything You Do In Terminal.md"};function c(m,s,g,h,v,x){const a=l("Link");return d(),o("div",null,[s[26]||(s[26]=t("h1",{id:"如何记录你在终端中执行的所有操作",tabindex:"-1"},[n("如何记录你在终端中执行的所有操作 "),t("a",{class:"header-anchor",href:"#如何记录你在终端中执行的所有操作","aria-label":"Permalink to 如何记录你在终端中执行的所有操作"},"​")],-1)),s[27]||(s[27]=t("p",null,[t("img",{src:"https://www.ostechnix.com/wp-content/uploads/2017/03/Record-Everything-You-Do-In-Terminal-720x340.png",alt:""})],-1)),t("p",null,[s[1]||(s[1]=n("几天前，我们发布了一个解释如何")),e(a,{href:"https://www.ostechnix.com/save-commands-terminal-use-demand/"},{default:p(()=>s[0]||(s[0]=[n("保存终端中的命令并按需使用")])),_:1}),s[2]||(s[2]=n("的指南。对于那些不想记忆冗长的 Linux 命令的人来说，这非常有用。今天，在本指南中，我们将看到如何使用 ")),s[3]||(s[3]=t("code",null,"script",-1)),s[4]||(s[4]=n(" 命令记录你在终端中执行的所有操作。你可能已经在终端中运行了一个命令，或创建了一个目录，或者安装了一个程序。")),s[5]||(s[5]=t("code",null,"script",-1)),s[6]||(s[6]=n(" 命令会保存你在终端中执行的任何操作。如果你想知道你几小时或几天前做了什么，那么你可以查看它们。我知道我知道，我们可以使用上/下箭头或 ")),s[7]||(s[7]=t("code",null,"history",-1)),s[8]||(s[8]=n(" 命令查看以前运行的命令。但是，你无法查看这些命令的输出。而 ")),s[9]||(s[9]=t("code",null,"script",-1)),s[10]||(s[10]=n(" 命令记录并显示完整的终端会话活动。"))]),s[28]||(s[28]=r(`<p><code>script</code> 命令会在终端中创建你所做的所有事件的记录。无论你是安装程序，创建目录/文件还是删除文件夹，一切都会被记录下来，包括命令和相应的输出。这个命令对那些想要一份交互式会话拷贝作为作业证明的人有用。无论是学生还是导师，你都可以将所有在终端中执行的操作和所有输出复制一份。</p><h3 id="在-linux-中使用-script-命令记录终端中的所有内容" tabindex="-1">在 Linux 中使用 script 命令记录终端中的所有内容 <a class="header-anchor" href="#在-linux-中使用-script-命令记录终端中的所有内容" aria-label="Permalink to 在 Linux 中使用 script 命令记录终端中的所有内容">​</a></h3><p><code>script</code> 命令预先安装在大多数现代 Linux 操作系统上。所以，我们不用担心安装。</p><p>让我们继续看看如何实时使用它。</p><p>运行以下命令启动终端会话记录。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ script -a my_terminal_activities</span></span></code></pre></div><p>其中，<code>-a</code> 标志用于将输出追加到文件（记录）中，并保留以前的内容。上述命令会记录你在终端中执行的所有操作，并将输出追加到名为 <code>my_terminal_activities</code> 的文件中，并将其保存在当前工作目录中。</p><p>示例输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Script started, file is my_terminal_activities</span></span></code></pre></div><p>现在，在终端中运行一些随机的 Linux 命令。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ mkdir ostechnix</span></span>
<span class="line"><span>$ cd ostechnix/</span></span>
<span class="line"><span>$ touch hello_world.txt</span></span>
<span class="line"><span>$ cd ..</span></span>
<span class="line"><span>$ uname -r</span></span></code></pre></div><p>运行所有命令后，使用以下命令结束 <code>script</code> 命令的会话：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ exit</span></span></code></pre></div><p>示例输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>exit</span></span>
<span class="line"><span>Script done, file is my_terminal_activities</span></span></code></pre></div><p>如你所见，终端活动已存储在名为 <code>my_terminal_activities</code> 的文件中，并将其保存在当前工作目录中。</p><p>要查看你的终端活动，只需在任何编辑器中打开此文件，或者使用 <code>cat</code> 命令直接显示它。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ cat my_terminal_activities</span></span></code></pre></div><p>示例输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Script started on Thu 09 Mar 2017 03:33:44 PM IST</span></span>
<span class="line"><span>[sk@sk]: ~&gt;$ mkdir ostechnix</span></span>
<span class="line"><span>[sk@sk]: ~&gt;$ cd ostechnix/</span></span>
<span class="line"><span>[sk@sk]: ~/ostechnix&gt;$ touch hello_world.txt</span></span>
<span class="line"><span>[sk@sk]: ~/ostechnix&gt;$ cd ..</span></span>
<span class="line"><span>[sk@sk]: ~&gt;$ uname -r</span></span>
<span class="line"><span>4.9.11-1-ARCH</span></span>
<span class="line"><span>[sk@sk]: ~&gt;$ exit</span></span>
<span class="line"><span>exit</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Script done on Thu 09 Mar 2017 03:37:49 PM IST</span></span></code></pre></div><p>正如你在上面的输出中看到的，<code>script</code> 命令记录了我所有的终端活动，包括 <code>script</code> 命令的开始和结束时间。真棒，不是吗？使用 <code>script</code> 命令的原因不仅仅是记录命令，还有命令的输出。简单地说，脚本命令将记录你在终端上执行的所有操作。</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to 结论">​</a></h3><p>就像我说的那样，脚本命令对于想要保留其终端活动记录的学生，教师和 Linux 用户非常有用。尽管有很多 CLI 和 GUI 可用来执行此操作，但 <code>script</code> 命令是记录终端会话活动的最简单快捷的方式。</p><p>就是这些。希望这有帮助。如果你发现本指南有用，请在你的社交，专业网络上分享，并支持我们。</p><p>干杯!</p><hr>`,26)),t("p",null,[s[12]||(s[12]=n("via: ")),e(a,{href:"https://www.ostechnix.com/record-everything-terminal/"},{default:p(()=>s[11]||(s[11]=[n("https://www.ostechnix.com/record-everything-terminal/")])),_:1})]),t("p",null,[s[17]||(s[17]=n("作者：")),e(a,{href:"https://www.ostechnix.com/author/sk/"},{default:p(()=>s[13]||(s[13]=[n("SK")])),_:1}),s[18]||(s[18]=n(" 选题：")),e(a,{href:"https://github.com/lujun9972"},{default:p(()=>s[14]||(s[14]=[n("lujun9972")])),_:1}),s[19]||(s[19]=n(" 译者：")),e(a,{href:"https://github.com/geekpi"},{default:p(()=>s[15]||(s[15]=[n("geekpi")])),_:1}),s[20]||(s[20]=n(" 校对：")),e(a,{href:"https://github.com/wxy"},{default:p(()=>s[16]||(s[16]=[n("wxy")])),_:1})]),t("p",null,[s[23]||(s[23]=n("本文由 ")),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>s[21]||(s[21]=[n("LCTT")])),_:1}),s[24]||(s[24]=n(" 原创编译，")),e(a,{href:"https://linux.cn/"},{default:p(()=>s[22]||(s[22]=[n("Linux中国")])),_:1}),s[25]||(s[25]=n(" 荣誉推出"))])])}const C=i(u,[["render",c]]);export{T as __pageData,C as default};
